import{_ as o,C as i,o as t,c as s,a3 as a,b as d,w as r,a as l,E as h,a4 as c}from"./chunks/framework.DhF4LrUq.js";const C=JSON.parse('{"title":"Rings and rollout","description":"Rings and rollout - the ordered ladder of audiences a release climbs, each ring with its own rules.","frontmatter":{"description":"Rings and rollout - the ordered ladder of audiences a release climbs, each ring with its own rules."},"headers":[],"relativePath":"concepts/rings-and-rollout.md","filePath":"concepts/rings-and-rollout.md"}'),g={name:"concepts/rings-and-rollout.md"};function p(u,e,m,f,b,v){const n=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="rings-and-rollout" tabindex="-1">Rings and rollout <a class="header-anchor" href="#rings-and-rollout" aria-label="Permalink to &quot;Rings and rollout&quot;">​</a></h1><p>Once a release is <code>ACTIVE</code>, distribution widens stage by stage through rings — an ordered ladder of audiences, each with its own rules. Rings are how &quot;test with five people, then the pilot tenant, then everyone&quot; becomes a governed, evidenced process instead of a hopeful one.</p><h2 id="the-five-default-rings" tabindex="-1">The five default rings <a class="header-anchor" href="#the-five-default-rings" aria-label="Permalink to &quot;The five default rings&quot;">​</a></h2><p>Every organization starts with the same five rings, in this order:</p><table tabindex="0"><thead><tr><th>Position</th><th>Ring</th><th>Typical audience</th></tr></thead><tbody><tr><td>0</td><td><code>engineering</code></td><td>Internal engineers dogfooding the build</td></tr><tr><td>1</td><td><code>qa</code></td><td>QA and structured test passes</td></tr><tr><td>2</td><td><code>tenant-pilot</code></td><td>The first real tenant population</td></tr><tr><td>3</td><td><code>uat</code></td><td>User acceptance testers</td></tr><tr><td>4</td><td><code>production</code></td><td>Everyone the release targets</td></tr></tbody></table><p>Organizations can customize the ladder: add rings, rename them, shadow a system ring with their own definition, and set each ring&#39;s rules. Only two things are fixed: the order is a strict ladder, and production stays last — a non-production ring can never take a position at or past it.</p><h2 id="what-each-ring-carries" tabindex="-1">What each ring carries <a class="header-anchor" href="#what-each-ring-carries" aria-label="Permalink to &quot;What each ring carries&quot;">​</a></h2><p>A ring is reference data plus rules:</p><ul><li><strong>Eligibility</strong> — which tenants and tester groups the ring admits. A ring with no eligibility rule admits every release target; rules narrow. At ring X, the audience is the release&#39;s targets intersected with the ring&#39;s rules.</li><li><strong>Approval policy</strong> — the named approval workflow that governs entering the ring.</li><li><strong>Quality gates</strong> — the required gate set attached to the ring (plus the organization-wide defaults).</li><li><strong>Promotion policy</strong> — manual or automatic (manual is the standing default).</li><li><strong>Channel reference</strong> — where the ring ships.</li></ul><p>Writing the production ring requires governance by default: it must carry an approval-policy reference and at least one required gate. The widest audience is never open by omission.</p><h2 id="the-governed-hop" tabindex="-1">The governed hop <a class="header-anchor" href="#the-governed-hop" aria-label="Permalink to &quot;The governed hop&quot;">​</a></h2><p>One action widens distribution: promote moves a release&#39;s targets one ring forward in the ladder — but only when every leg of the target ring&#39;s evaluation passes, evaluated live at the moment of the call:</p>',12)),(t(),d(c,null,{default:r(()=>[h(n,{id:"mermaid-129",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20ACTIVE%5B%22ACTIVE%20release%3Cbr%2F%3Etargets%20on%20ring%20N%22%5D%0A%20%20%20%20HOP%5B%22Promote%3Cbr%2F%3Eone%20ring%20forward%22%5D%0A%20%20%20%20GATES%7B%22Target%20ring's%3Cbr%2F%3Erequired%20gates%3Cbr%2F%3Epassed%3F%22%7D%0A%20%20%20%20POLICY%7B%22Approval%20policy%3Cbr%2F%3Esatisfied%20for%3Cbr%2F%3Ethis%20ring%3F%22%7D%0A%20%20%20%20ELIG%7B%22Every%20moved%20tenant%3Cbr%2F%3Eadmitted%20by%20the%3Cbr%2F%3Ering's%20rules%3F%22%7D%0A%20%20%20%20RULES%7B%22Standing%20release%3Cbr%2F%3Epolicies%3Cbr%2F%3E(BLOCK%20%2F%20HOLD)%20fired%3F%22%7D%0A%20%20%20%20NEXT%5B%22Targets%20move%20to%20ring%20N%2B1%3Cbr%2F%3Eevidence%20recorded%22%5D%0A%20%20%20%20BLOCKED%5B%22409%20with%20the%20COMPLETE%3Cbr%2F%3Eblocker%20list%20%2B%20evidence%3Cbr%2F%3Eon%20the%20promotions%20timeline%22%5D%0A%20%20%20%20FINAL%5B%22Final%20ring%20reached%3Cbr%2F%3Erelease%20crosses%20to%20PROMOTED%22%5D%0A%0A%20%20%20%20ACTIVE%20--%3E%20HOP%0A%20%20%20%20HOP%20--%3E%20GATES%0A%20%20%20%20GATES%20--%3E%7C%22yes%22%7C%20POLICY%0A%20%20%20%20GATES%20--%3E%7C%22no%20%E2%80%94%20evidence%20URL%20named%22%7C%20BLOCKED%0A%20%20%20%20POLICY%20--%3E%7C%22yes%20or%20none%20bound%22%7C%20ELIG%0A%20%20%20%20POLICY%20--%3E%7C%22pending%20or%20unresolved%22%7C%20BLOCKED%0A%20%20%20%20ELIG%20--%3E%7C%22yes%22%7C%20RULES%0A%20%20%20%20ELIG%20--%3E%7C%22excluded%20tenants%20named%22%7C%20BLOCKED%0A%20%20%20%20RULES%20--%3E%7C%22no%22%7C%20NEXT%0A%20%20%20%20RULES%20--%3E%7C%22BLOCK%20%2F%20unacknowledged%20HOLD%22%7C%20BLOCKED%0A%20%20%20%20NEXT%20--%3E%7C%22not%20final%22%7C%20ACTIVE%0A%20%20%20%20NEXT%20--%3E%7C%22final%20ring%20for%20every%20target%22%7C%20FINAL%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>A refused attempt answers <code>RELEASE_PROMOTION_BLOCKED</code> carrying the complete blocker list — each blocking gate with its evidence, the approval standing, any excluded tenant with its reason, and every policy refusal — and records that refusal on the append-only promotions timeline. The same evaluation is available as a read (the precheck), so &quot;why can&#39;t I promote?&quot; is a screen, not a support ticket.</p><h2 id="how-the-hops-behave" tabindex="-1">How the hops behave <a class="header-anchor" href="#how-the-hops-behave" aria-label="Permalink to &quot;How the hops behave&quot;">​</a></h2><ul><li><strong>The default hop is exactly one ring forward.</strong> Skipping is refused unless the organization explicitly widens its skip allowances — and even then, forward only, with every policy admitting the hop.</li><li><strong>A move set must sit on one ring.</strong> Promote moves every target, or the selective tenants you name (Acme first, Contoso later). A set straddling rings is refused with each tenant&#39;s ring named.</li><li><strong>A policy-gated ring opens an approval round on the first attempt.</strong> The attempt answers blocked-on-the-round; approvers decide; the next attempt proceeds when satisfied. A rejected round&#39;s rework path is the next promote attempt.</li><li><strong>Promotion never mutates artifacts.</strong> The engine moves ring ids and writes timelines, audits, and events — the artifact SHA-256s and the frozen manifest stay untouched by construction.</li><li><strong>Concurrent promotions are serialized.</strong> A concurrent hop that moved a target first answers a precise conflict; nothing partially moves.</li></ul><h2 id="staged-tenant-rollout" tabindex="-1">Staged tenant rollout <a class="header-anchor" href="#staged-tenant-rollout" aria-label="Permalink to &quot;Staged tenant rollout&quot;">​</a></h2><p>Inside the final ring, distribution can stage across the tenant population — pilot tenants, then a percentage of tenants, advancing in stages — with a one-action rollback that cuts direct downloads, reverts store assignments, and records everything. Apps that opted into <a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates</a> stage by deterministic device buckets instead, on a ring whose channel is <code>ota</code>. The staged rollout walk-through is a Console how-to; this page is the model it rides.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/approvals-gates">Approvals and gates</a> — the two engines the hop consults</li><li><a href="/shipperdog/snapshot/concepts/feedback-analytics">Feedback and analytics</a> — where the metric-backed gate values come from</li><li>Developer detail: the rings and promotion sections of the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/releases.md" target="_blank" rel="noreferrer">releases</a> module doc.</li></ul>',7))])}const w=o(g,[["render",p]]);export{C as __pageData,w as default};
